/**
 * N5-1a + review of wave 1A: the build knows the migrations it ships without reading the repository at
 * runtime (Railway runs `next start` from a build whose layout is not ours to rely on). Readiness used
 * to check only the NEWEST one, so a database missing an older migration of the same bundle (156 with
 * 157 recorded) passed. The constant is now the list of every migration of the bundle era (≥ 140),
 * generated by scripts/deploy/check-migrations.mjs and pinned here (and by that script in CI) to the folder.
 */
import { readdirSync, readFileSync } from 'node:fs'
import path from 'node:path'
import { describe, expect, it } from 'vitest'
import { NEWEST_MIGRATION, SCHEMA_CHECK_FROM, SHIPPED_MIGRATIONS } from '@/lib/health/schema-version'
import {
  ROLLBACK_REQUIRED_FROM,
  SHIPPED_FROM,
  checkShippedConstant,
  newestMigration,
  parseShippedConstant,
  renderSchemaVersion,
  shippedMigrations,
} from '../../../scripts/deploy/check-migrations.mjs'

const ROOT = path.resolve(__dirname, '../../..')
const DIR = path.join(ROOT, 'supabase/migrations')
const SOURCE = path.join(ROOT, 'lib/health/schema-version.ts')
const filesInFolder = () => readdirSync(DIR).filter((f) => /^\d{3}_[a-z0-9_]+\.sql$/.test(f)).sort()

describe('SHIPPED_MIGRATIONS', () => {
  it('is every NNN_*.sql numbered 140 or more in supabase/migrations, in order (add a migration → regenerate)', () => {
    const expected = filesInFolder().filter((f) => Number(f.slice(0, 3)) >= 140)
    expect([...SHIPPED_MIGRATIONS]).toEqual(expected)
    expect(expected.length).toBeGreaterThanOrEqual(19) // 140 … 158 at the time of the review
    expect(SCHEMA_CHECK_FROM).toBe(140)
    expect(SHIPPED_FROM).toBe(SCHEMA_CHECK_FROM)
    expect(SHIPPED_FROM).toBe(ROLLBACK_REQUIRED_FROM) // the bundle era: rollbacks and the journal check start together
  })

  it('NEWEST_MIGRATION is its last element and the newest file of the folder', () => {
    expect(NEWEST_MIGRATION).toBe(SHIPPED_MIGRATIONS[SHIPPED_MIGRATIONS.length - 1])
    expect(NEWEST_MIGRATION).toBe(filesInFolder().at(-1))
  })

  it('the file is exactly what the generator writes (node scripts/deploy/check-migrations.mjs --write-schema-version)', () => {
    expect(readFileSync(SOURCE, 'utf8')).toBe(renderSchemaVersion(shippedMigrations(filesInFolder())))
  })
})

describe('check-migrations guards the list', () => {
  const src = readFileSync(SOURCE, 'utf8')
  const files = filesInFolder()

  it('the current source passes', () => {
    expect(checkShippedConstant(files, src)).toEqual([])
    expect(parseShippedConstant(src)).toEqual({ from: 140, files: [...SHIPPED_MIGRATIONS] })
  })

  it('a missing file of the bundle era (not only the newest) is refused, naming it and the command', () => {
    const without156 = src.replace(/\n\s*'156_[a-z0-9_]+\.sql',/, '')
    expect(without156).not.toBe(src)
    const problems = checkShippedConstant(files, without156)
    expect(problems).toEqual([expect.stringMatching(/нет 156_archive_legacy_crm_integrations\.sql[\s\S]*--write-schema-version/)])
  })

  it('a stale list (a new migration not added) and a file that is not in the folder are refused', () => {
    expect(checkShippedConstant([...files, '159_next.sql'], src)).toEqual([expect.stringContaining('нет 159_next.sql')])
    const extra = src.replace(`'${NEWEST_MIGRATION}',`, `'${NEWEST_MIGRATION}',\n  '199_ghost.sql',`)
    expect(checkShippedConstant(files, extra)).toEqual([expect.stringContaining('лишняя 199_ghost.sql')])
  })

  it('no list, or another start number, is refused', () => {
    expect(checkShippedConstant(files, '// nothing here')).toEqual([expect.stringContaining('SHIPPED_MIGRATIONS не найден')])
    expect(checkShippedConstant(files, src.replace('SCHEMA_CHECK_FROM = 140', 'SCHEMA_CHECK_FROM = 150'))).toEqual([expect.stringContaining('SCHEMA_CHECK_FROM = 150')])
  })

  it('shippedMigrations keeps only valid files from 140 on; newestMigration picks the highest number', () => {
    expect(shippedMigrations(['001_a.sql', '139_b.sql', '140_c.sql', 'README.md', '141_d.down.sql', '157_e.sql'])).toEqual(['140_c.sql', '157_e.sql'])
    expect(newestMigration(['001_a.sql', '157_b.sql', '099_c.sql', 'README.md', '158_x.down.sql'])).toBe('157_b.sql')
    expect(newestMigration([])).toBeNull()
  })
})
